import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as _ } from '@/primitives';
import { createNode as __ } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for the node
  const root = new Group();
  root.name = config.id ?? 'collection-card-1';

  // Geometry – default 1×1 plane (will be scaled by external transform if needed)
  const geometry = new PlaneGeometry(1, 1, 1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  mesh.name = 'card-plane';
  root.add(mesh);

  // Load texture and apply to material
  let pendingTexture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      pendingTexture = tex;
    })
    .catch(() => {
      // Silently ignore missing texture; keep plane untextured
    });

  // Store references for cleanup
  const timelines = [];

  // Placeholder for potential future primitives (none in this spec)
  const primitiveHandles = [];

  // Attach empty handlers object as required by the runtime contract
  root.userData.handlers = {};

  // Cleanup routine – disposes all resources and kills GSAP timelines
  root.userData.cleanup = () => {
    // Cancel any pending texture load (no built‑in cancel, just ignore result)
    // Dispose material and geometry
    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines we might have created
    timelines.forEach((tl) => tl.kill());

    // Cleanup any primitives (none for this node, but follow spec)
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
  };

  // Return the assembled object
  return root;
}
